@icontract.ensure(lambda nums, rems, OLD: rems == OLD.rems_before)
@icontract.ensure(lambda nums, rems: len(nums) == len(rems))
@icontract.ensure(lambda nums: len(nums) > 0)
@icontract.ensure(lambda nums: all(gcd(nums[i], nums[j]) == 1 for i in range(len(nums)) for j in range(i + 1, len(nums))))
@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda result, nums: result < __import__('math').prod(nums))
